#include <SPI.h>
#include <TFT_eSPI.h>
#include <XPT2046_Touchscreen.h>

// CYD display settings
#define ILI9341_DRIVER
#define TFT_MISO 12
#define TFT_MOSI 13
#define TFT_SCLK 14
#define TFT_CS   15
#define TFT_DC   2
#define TFT_RST  -1
#define TFT_BL   21

// Touchscreen pins
#define TOUCH_CS 33
#define TOUCH_IRQ 36

TFT_eSPI tft = TFT_eSPI();

SPIClass touchSPI(HSPI);
XPT2046_Touchscreen touch(TOUCH_CS, TOUCH_IRQ);

uint16_t colors[] = {
  TFT_BLACK,
  TFT_WHITE,
  TFT_RED,
  TFT_GREEN,
  TFT_BLUE,
  TFT_YELLOW,
  TFT_MAGENTA,
  TFT_CYAN
};

int selectedColor = 2;
int brushSize = 4;
bool eraser = false;

int lastX = -1;
int lastY = -1;

const int TOOLBAR_HEIGHT = 65;

void drawToolbar() {
  tft.fillRect(0, 0, 320, TOOLBAR_HEIGHT, TFT_DARKGREY);

  // 8 color buttons
  for (int i = 0; i < 8; i++) {
    int x = i * 40;
    tft.fillRect(x + 5, 5, 30, 25, colors[i]);

    if (i == selectedColor) {
      tft.drawRect(x + 3, 3, 34, 29, TFT_WHITE);
    }
  }

  // Brush sizes
  tft.setTextColor(TFT_WHITE);
  tft.setTextSize(1);

  tft.drawString("Small", 8, 43);
  tft.drawString("Medium", 65, 43);
  tft.drawString("Large", 135, 43);

  tft.drawRect(5, 39, 48, 22, TFT_WHITE);
  tft.drawRect(60, 39, 60, 22, TFT_WHITE);
  tft.drawRect(125, 39, 55, 22, TFT_WHITE);

  // Eraser and clear buttons
  tft.drawRect(190, 39, 55, 22, TFT_WHITE);
  tft.drawString("Eraser", 198, 43);

  tft.drawRect(255, 39, 58, 22, TFT_WHITE);
  tft.drawString("Clear", 265, 43);
}

void setup() {
  Serial.begin(115200);

  pinMode(TFT_BL, OUTPUT);
  digitalWrite(TFT_BL, HIGH);

  tft.init();
  tft.setRotation(1);
  tft.fillScreen(TFT_WHITE);

  touchSPI.begin(25, 39, 32, TOUCH_CS);
  touch.begin(touchSPI);
  touch.setRotation(1);

  drawToolbar();

  tft.fillRect(0, TOOLBAR_HEIGHT, 320,
               240 - TOOLBAR_HEIGHT, TFT_WHITE);
}

void loop() {
  if (!touch.touched()) {
    lastX = -1;
    lastY = -1;
    return;
  }

  TS_Point p = touch.getPoint();

  // Convert touchscreen coordinates
  int x = map(p.y, 200, 3700, 0, 320);
  int y = map(p.x, 200, 3700, 240, 0);

  x = constrain(x, 0, 319);
  y = constrain(y, 0, 239);

  // Color selection
  if (y < 35) {
    selectedColor = constrain(x / 40, 0, 7);
    eraser = false;
    drawToolbar();
    lastX = -1;
    return;
  }

  // Tool selection
  if (y < TOOLBAR_HEIGHT) {
    if (x < 55) {
      brushSize = 2;
    }
    else if (x < 125) {
      brushSize = 4;
    }
    else if (x < 185) {
      brushSize = 8;
    }
    else if (x < 250) {
      eraser = true;
    }
    else {
      // Clear canvas
      tft.fillRect(0, TOOLBAR_HEIGHT, 320,
                   240 - TOOLBAR_HEIGHT, TFT_WHITE);
    }

    lastX = -1;
    return;
  }

  // Drawing
  uint16_t drawColor = eraser ? TFT_WHITE : colors[selectedColor];

  if (lastX == -1) {
    tft.fillCircle(x, y, brushSize, drawColor);
  } else {
    tft.drawLine(lastX, lastY, x, y, drawColor);
    tft.fillCircle(x, y, brushSize, drawColor);
  }

  lastX = x;
  lastY = y;
}
